<script setup>
import Icon from './Icon.vue'
defineProps({rows:{default:()=>[]},actions:Boolean})
defineEmits(['edit','remove','email'])
</script>
<template><div class="table-scroll"><table class="data-table"><thead><tr><th>ESTUDIANTE</th><th>ASIGNATURA / GRUPO</th><th>EVALUACIÓN</th><th>NOTA</th><th>ESTADO</th><th v-if="actions" class="text-right">ACCIONES</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="row.id"><td><div class="student-cell"><span class="student-avatar" :class="'tone-'+i%4">{{row.student?.name?.split(' ').slice(0,2).map(x=>x[0]).join('')}}</span><div><strong>{{row.student?.name}}</strong><small>{{row.student?.student_code}}</small></div></div></td><td><strong class="subject-name">{{row.group?.subject}}</strong><small class="subtext">{{row.group?.code}} · {{row.group?.cycle}}</small></td><td><span class="evaluation-chip">Parcial {{row.evaluation}}</span></td><td><strong class="score" :class="{failed:row.score<6}">{{Number(row.score).toFixed(2)}}</strong><span class="score-max"> / 10</span></td><td><span class="status-badge" :class="row.score>=6?'passed':'failed'"><span></span>{{row.score>=6?'Aprobado':'Reprobado'}}</span></td><td v-if="actions"><div class="row-actions"><button title="Enviar nota por correo" aria-label="Enviar nota por correo" @click="$emit('email',row)"><Icon name="Mail" :size="17"/></button><button title="Editar nota" aria-label="Editar nota" @click="$emit('edit',row)"><Icon name="Pencil" :size="17"/></button><button class="danger" title="Eliminar nota" aria-label="Eliminar nota" @click="$emit('remove',row)"><Icon name="Trash2" :size="17"/></button></div></td></tr><tr v-if="!rows.length"><td :colspan="actions?6:5"><div class="empty-state"><Icon name="BookOpen" :size="30"/><strong>No hay notas registradas</strong><p>Los registros aparecerán aquí cuando guardes una evaluación.</p></div></td></tr></tbody></table></div></template>
